// План specs/admin-plans.md, 1.2 (кейс AP-01, HE). Только чтение. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage } from './plans-helpers';
import { accountRows, loadedRowCount, openPlansTabNamed } from './plans-read-helpers';

test.use({ storageState: '../auth/admin.json' });

test.describe('Admin Panel — Plans', () => {
  test('Plans tab in Hebrew shows translated tab, filters and columns #ca557707 @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'he');
    await openPlansTabNamed(page, 'חבילות');

    // RTL: у html или у корневого контейнера
    // не проверено на сайте: где именно стоит dir="rtl".
    await expect(page.locator('html[dir="rtl"], body[dir="rtl"], #root[dir="rtl"], #root > [dir="rtl"], body > div[dir="rtl"]').first()).toBeAttached();

    // не проверено на сайте: подпись фильтра читается как текст combobox (кастомный) или выбранный option (<select>).
    for (const label of ['כל החבילות', 'כל המקורות', 'כל הסטטוסים']) {
      await expect(page.getByRole('combobox').filter({ hasText: label })
        .or(page.getByRole('combobox', { name: label })).first()).toBeVisible();
    }

    for (const header of ['חשבון', 'חבילה', 'מקור', 'סטטוס מנוי', 'עד']) {
      await expect(page.locator('th, [role="columnheader"]').filter({ hasText: new RegExp(`^${header}$`) }).first()).toBeVisible();
    }

    // Кнопки в строках без ручного назначения — на иврите
    await loadedRowCount(page);
    await expect(accountRows(page).getByRole('button', { name: 'הקצה חבילה', exact: true }).first()).toBeVisible();
    await expect(page.getByRole('button', { name: 'Assign plan', exact: true })).toHaveCount(0);
  });
});
